package com.codeguardian.service.tools; import com.codeguardian.entity.Finding; import org.springframework.stereotype.Component; import java.io.*; import java.nio.file.*; import java.util.*; @Component public class SemgrepAnalysisTool{public List<Finding> analyze(String code){try{Path file=Files.createTempFile("codeguardian-",".txt");Files.writeString(file,code);Process p=new ProcessBuilder("semgrep","--config","auto","--json",file.toString()).redirectErrorStream(true).start();String out=new String(p.getInputStream().readAllBytes());p.waitFor();Files.deleteIfExists(file);return List.of();}catch(Exception e){return List.of();}}}
